module game_scores(\n    input [1:0] start_player,\n    input [4:0] start_number,\n    output reg [7:0] score_O,\n    output reg [7:0] score_E,\n    output reg [7:0] score_I\n);\n\n    reg [23:0] rom [0:59];\n\n    initial begin\n        $readmemh(\"rom_data.hex\", rom);\n    end\n\n    always @(*) begin\n        reg [5:0] index;\n        if (start_number >= 5'd1 && start_number <= 5'd20) begin\n            index = {start_player, 5'd0} + (start_number - 5'd1);\n        end else begin\n            index = 6'd0;\n        end\n        {score_O, score_E, score_I} = rom[index];\n    end\n\nendmodule